p echo $string['content']; ?></td><td><?php echo $string['access']; ?></td><td><?php echo $string['deleted']; ?></td></tr><?php  $result = $mysqli->prepare("SELECT id, title, body_plain, roles, DATE_FORMAT(deleted,'$cfg_long_date_time') AS deleted FROM staff_help WHERE deleted IS NOT NULL ORDER BY title");  $result->execute();  $result->store_result();  $result->bind_result($id, $title, $body, $tmp_roles, $deleted);  if ($result->num_rows == 0) {    echo "<p>" . $string['empty'] . "</p>\n";  } else {    while ($result->fetch()) {      if ($body == '') $body = '&nbsp;';      echo "<tr><td><a href=\"" . $_SERVER['PHP_SELF'] . "?id=$id\"><img src=\"../../artwork/restore.png\" width=\"16\" height=\"16\" border=\"0\" alt=\"" . $string['restore'] . "\" /></a></td><td><nobr>$title</nobr></td><td>$body</td><td>$tmp_roles</td><td><nobr>$deleted</nobr></td></tr>\n";    }  }    $mysqli->close();?></table></body></html>